def has_pair_with_sum(nums, target):
    seen = set()
    for num in nums:
        complement = target - num
        if complement in seen:
            return True
        seen.add(num)
    return False

def pluralize(word, count):
    if count == 1:
        return word

    vowels = 'aeiou'

    if word.endswith('y') and len(word) >= 2 and word[-2].lower() not in vowels:
        return word[:-1] + 'ies'

    if word.endswith(('s', 'x', 'ch', 'sh')):
        return word + 'es'

    return word + 's'

def dedupe_preserve_order(items):
    seen = set()
    result = []
    for item in items:
        key = item.strip().lower()
        if key not in seen:
            seen.add(key)
            result.append(item)
    return result
